scripts.script:
if (args.isBroken) {
    const shizhun = args.target.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'shizhun');
    if (shizhun) {
        const stacks = shizhun.getFlag('xjzl-system', 'stacks') || 1;
        await game.xjzl.api.effects.removeEffect(args.target, 'shizhun', stacks);
        const bleedData = CONFIG.statusEffects.find(e => e.id === 'bleed_stack');
        if (bleedData) {
            await game.xjzl.api.effects.addEffect(args.target, bleedData, stacks);
            ui.notifications.info(`${args.target.name} 体内寒气爆发，${stacks} 层失准转化为流血！`);
        }
    }
}

if (Macros.checkStance(actor, args)) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'shizhun');
    if (eff) {
        const data = foundry.utils.deepClone(eff);
        foundry.utils.setProperty(data, 'flags.xjzl-system.maxStacks', 3);
        await game.xjzl.api.effects.addEffect(args.attacker, data);
    }
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'shizhun');
    if (eff) {
        const data = foundry.utils.deepClone(eff);
        foundry.utils.setProperty(data, 'flags.xjzl-system.maxStacks', 3);
        await game.xjzl.api.effects.addEffect(args.target, data);
    }
}

if (args.move.weaponType === 'blade' && actor.system.resources.rage.value >= 2) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: '悟刀' },
        content: '<p>是否消耗 2 点怒气获得一种劲力？</p>',
        rejectClose: false
    });
    if (confirm) {
        await actor.update({'system.resources.rage.value': actor.system.resources.rage.value - 2});
        const selection = await foundry.applications.api.DialogV2.wait({
            window: { title: '选择劲力' },
            content: '<p>请选择要获得的劲力：</p>',
            buttons: [
                { action: 'gangjin', label: '刚劲 (+刚伤)', icon: 'fas fa-fist-raised' },
                { action: 'mianjin', label: '绵劲 (+柔伤)', icon: 'fas fa-water' },
                { action: 'juqi', label: '聚气 (回蓝)', icon: 'fas fa-bolt' },
                { action: 'xujin', label: '蓄劲 (暴击)', icon: 'fas fa-crosshairs' }
            ],
            close: () => null
        });
        if (selection) {
            const eff = CONFIG.statusEffects.find(e => e.id === selection);
            if (eff) await game.xjzl.api.effects.addEffect(actor, eff);
        }
    }
}

const eff = thisItem.effects.getName('大朝妙计').toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);

const juqi = actor.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'juqi');
const stacks = juqi ? (juqi.getFlag('xjzl-system', 'stacks') || 1) : 0;
const range = 1 + stacks;
args.output.bonusDesc.push(`当前范围: ${range}米 (聚气加成)`);
const qingling = actor.effects.some(e => e.getFlag('xjzl-system', 'slug') === 'qingling');
if (qingling) args.output.bonusDesc.push('轻灵激活：可掠至目标位置并攻击路径敌人。');

if (args.isHit && !args.target.system.martial.stanceActive) {
    const juqi = actor.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'juqi');
    if (juqi) {
        const currentStacks = juqi.getFlag('xjzl-system', 'stacks') || 1;
        const maxSpend = Math.min(currentStacks, 3);
        const confirm = await foundry.applications.api.DialogV2.confirm({
            window: { title: '千秋飞历' },
            content: `<p>击中未招架敌人！是否消耗至多 ${maxSpend} 层聚气施加流血？</p>`,
            rejectClose: false
        });
        if (confirm) {
            await game.xjzl.api.effects.removeEffect(actor, 'juqi', maxSpend);
            const bleedData = CONFIG.statusEffects.find(e => e.id === 'bleed_stack');
            await game.xjzl.api.effects.addEffect(args.target, bleedData, maxSpend);
            ui.notifications.info(`${actor.name} 消耗 ${maxSpend} 层聚气，使目标流血！`);
        }
    }
}

if (args.isBroken) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'qingling');
    if(eff) await game.xjzl.api.effects.addEffect(actor, eff);
}

if (Macros.checkStance(actor, args)) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'juqi');
    if(eff) await game.xjzl.api.effects.addEffect(actor, eff);
}

if (args.isHit) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const stacks = 1 + (lvl - 1);
    const eff = CONFIG.statusEffects.find(e => e.id === 'chanshou');
    if (eff) await game.xjzl.api.effects.addEffect(args.target, eff, stacks);

    // 绵劲检测
    const mianjin = actor.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'mianjin');
    if (mianjin) {
        ChatMessage.create({
            content: `<div class='xjzl-chat-card'><div style='padding:5px;'><b>绵劲追击：</b><br>可消耗 1 层绵劲获得次要动作。<br>可消耗 3 层绵劲获得主要动作。</div></div>`,
            speaker: ChatMessage.getSpeaker({actor: actor})
        });
    }
}

if (args.isBroken) {
    const mianjin = actor.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'mianjin');
    if (mianjin) {
        ui.notifications.info("击破且有绵劲！可消耗1层绵劲，飞跃并消耗反应再次施展！");
    }
}

if (Macros.checkStance(actor, args)) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'mianjin');
    if(eff) await game.xjzl.api.effects.addEffect(actor, eff);
}

if (args.isHit) {
    const gangjin = actor.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'gangjin');
    if (gangjin) {
        ui.notifications.info(`${args.target.name} 被击退 1 米！`);
    }
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'gangjin');
    if(eff) await game.xjzl.api.effects.addEffect(actor, eff);
}

if (args.isBroken) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'chizhi');
    if(eff) {
        const data = foundry.utils.deepClone(eff);
        data.duration = { rounds: 1 };
        await game.xjzl.api.effects.addEffect(args.target, data);
    }
}

if (Macros.checkStance(actor, args)) {
    ui.notifications.info("格挡成功，击退对手 1 米！");
}

const eff = thisItem.effects.getName('汇刀谱监听').toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);

if (args.item.name.includes('绣春刀法')) {
    const ranks = actor.system.combat.weaponRanks;
    if (ranks.unarmed.total >= 6 && args.move.type === 'stance') {
        args.output.damage += 5;
        args.output.bonusDesc.push('汇刀谱(徒手): 格挡+5');
    }
    if (ranks.sword.total >= 6 && args.move.type === 'real') {
        args.output.damage += 20;
        args.output.bonusDesc.push('汇刀谱(剑): 伤害+20');
    }
    if (ranks.dagger.total >= 6 && args.move.type === 'counter') {
        args.output.damage += 20;
        args.output.bonusDesc.push('汇刀谱(匕首): 伤害+20');
    }
    if (ranks.hidden.total >= 6 && args.move.type === 'feint') {
        args.output.damage += 20;
        args.output.bonusDesc.push('汇刀谱(暗器): 伤害+20');
    }
    if (ranks.special.total >= 6 && args.move.type === 'feint') {
        args.output.feint += 3;
    }
    if (ranks.staff.total >= 6 && args.move.type === 'real') {
        args.output.bonusDesc.push('汇刀谱(棍): 距离+1 (文本提示)');
    }
}

const rep = actor.system.social.rep_chaoting || 0;
const bonus = rep * 5;
S.resources.hp.bonus = (S.resources.hp.bonus || 0) + bonus;
S.resources.mp.bonus = (S.resources.mp.bonus || 0) + bonus;

if (args.isHit && !args.target.system.martial.stanceActive) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'bleed_stack');
    if(eff) await game.xjzl.api.effects.addEffect(args.target, eff);
}

if (Macros.checkStance(actor, args) && args.attacker) {
    await Macros.requestContest({
        attacker: actor,
        defender: args.attacker,
        type: "jiaoli",
        defType: "jiaoli",
        label: "诏狱缚 - 角力对抗",
        outcome: {
            win: { text: "缠绕成功：目标失去武器操纵权！" },
            lose: { text: "目标抽回了武器。" }
        }
    });
}

if (args.isBroken) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'fushen');
    if(eff) await game.xjzl.api.effects.addEffect(args.target, eff);
    const lvl = Math.max(1, move.computedLevel || 1);
    const dc = 15 + (lvl - 1) * 2;
    ui.notifications.info(`${args.target.name} 被擒抱！挣脱难度 DC ${dc}。`);
}

if (args.isHit) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'blind');
    if (eff) {
        const data = foundry.utils.deepClone(eff);
        data.duration = { rounds: 3 };
        await game.xjzl.api.effects.addEffect(args.target, data);
    }
}

if (Macros.checkStance(actor, args)) {
    // 获取当前架招等级
    const stanceId = actor.system.martial.stance;
    const moveData = thisItem.system.moves.find(m => m.id === stanceId);
    const lvl = Math.max(1, moveData?.computedLevel || 1);
    const dist = 1 + (lvl - 1);
    ui.notifications.info(`格挡成功！可向后移动 ${dist} 米。`);
}

if (args.isBroken) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'prone');
    if(eff) await game.xjzl.api.effects.addEffect(args.target, eff);
    ui.notifications.info(`${args.target.name} 被击退 1 米并倒地！`);
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const eff = CONFIG.statusEffects.find(e => e.id === 'unstable');
    if (eff) {
        const data = foundry.utils.deepClone(eff);
        data.duration = { rounds: 1 };
        await game.xjzl.api.effects.addEffect(args.target, data);
    }
}

if (args.isHit) {
    const eff = thisItem.effects.getName("骨裂").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, eff);
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    // 1. 施加倒地
    await game.xjzl.api.effects.addEffect(args.target, "prone");

    // 2. 计算落地伤害 (基础20 + 升级10)
    const lvl = Math.max(1, move.computedLevel || 1);
    const fallDmg = 20 + (lvl - 1) * 10;

    // 3. 应用额外伤害
    await args.target.applyDamage({ 
        amount: fallDmg, 
        type: "waigong", 
        attacker: actor 
    });

    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div class="card-content-wrapper"><b>击飞提示：</b><br>目标已倒地并受到落地伤害。<br>请手动移动目标 <b>3米</b>。</div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (!Macros.checkStance(actor, args)) return;
if (!args.attacker) return;

// 1. 查找招式等级
const stanceId = actor.system.martial.stance;
const moveData = thisItem.system.moves.find(m => m.id === stanceId);
const lvl = Math.max(1, moveData?.computedLevel || 1);

// 2. 计算反震伤害 (基础10 + 升级10)
const reflectDmg = 10 + (lvl - 1) * 10;

// 3. 应用伤害
await args.attacker.applyDamage({
    amount: reflectDmg,
    type: "waigong",
    attacker: actor,
    ignoreDefense: true,
    isHit: true
});

actor.showFloatyText("反震!", { fill: "#FFA500" });

const hasBoneCrack = args.target.effects.some(e => e.name === "骨裂");
if (hasBoneCrack) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div class="card-content-wrapper" style="color:#8b0000;"><b><i class="fas fa-bone"></i> 粉碎性打击！</b><br>目标具有[骨裂]，请GM判定其一手或一腿断裂（骨折）。</div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.type === "waigong") {
    await actor.applyDamage({ amount: 20, type: "liushi", attacker: args.attacker });
    actor.showFloatyText("骨裂疼痛", { fill: "#FF0000" });
}

if (args.isBroken) {
    await game.xjzl.api.effects.addEffect(args.target, "fushen");
    const eff = args.target.effects.find(e => e.getFlag("xjzl-system", "slug") === "fushen");
    if (eff) await eff.update({ "duration.rounds": 2 });
    ui.notifications.info(`${args.target.name} 被缚身！`);
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    await game.xjzl.api.effects.addEffect(args.target, "prone");

    // 下盘不稳持续1回合
    const unstable = CONFIG.statusEffects.find(e => e.id === "unstable");
    const data = foundry.utils.deepClone(unstable);
    data.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.target, data);
}

if (Macros.checkStance(actor, args)) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div class="card-content-wrapper"><p><b>束带揽魂触发：</b></p><p>可消耗反应动作施展 <b>[阴煞贯棍]</b>。</p></div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

const lvl = Math.max(1, move.computedLevel || 1);
const healPerUnit = 10 + (lvl - 1) * 10;

const count = await foundry.applications.api.DialogV2.prompt({
    window: { title: "黄泉引渡" },
    content: `<div class="form-group"><label>周围尸傀数量</label><input type="number" name="count" min="0" value="0" autofocus></div>`,
    ok: { callback: (event, button) => button.form.elements.count.value }
});

if (count > 0) {
    const totalHeal = count * healPerUnit;
    await actor.applyHealing({ amount: totalHeal, type: "hp", showScrolling: true });
    ui.notifications.info(`尸傀(${count}) 共回复 ${totalHeal} 气血`);
}

if (args.isHit) {
    const count = await foundry.applications.api.DialogV2.prompt({
        window: { title: `目标 ${args.target.name} 周围尸傀` },
        content: `<div class="form-group"><label>3米内尸傀数量</label><input type="number" name="count" min="0" value="0" autofocus></div>`,
        ok: { callback: (event, button) => button.form.elements.count.value }
    });

    if (count > 0) {
        // 1. 流失伤害
        const loss = count * 20;
        await args.target.applyDamage({ amount: loss, type: "liushi", attacker: actor });

        // 2. 超过3个施加控制
        if (count > 3) {
            await game.xjzl.api.effects.addEffect(args.target, "fushen");
            await game.xjzl.api.effects.addEffect(args.target, "chizhi");

            // 统一调整持续时间 (系统状态默认可能不同，这里强制设为1回合)
            // 注意：addEffect 返回的是 Document，如果需要修改需要 update
            // 为简化，我们提示状态已加。
            ui.notifications.info(`${args.target.name} 被尸群围困 (缚身/迟滞)`);
        }
    }
}

const eff = thisItem.effects.getName("巫坛").toObject();
delete eff._id;
eff.origin = thisItem.uuid;

// 动态写入减伤值 (基础10 + 升级5)
const lvl = Math.max(1, move.computedLevel || 1);
const reduction = 10 + (lvl - 1) * 5;
eff.flags["xjzl-system"].damageReduction = reduction;
eff.description += ` (当前减免: ${reduction})`;

await game.xjzl.api.effects.addEffect(actor, eff);

if (args.isBroken) {
    const eff = thisItem.effects.getName("渡魂").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    eff.duration = { rounds: 2 };
    await game.xjzl.api.effects.addEffect(args.target, eff);
}

const lvl = Math.max(1, move.computedLevel || 1);
const huti = 20 + (lvl - 1) * 10;

// 提示移除状态与护体
ChatMessage.create({
    content: `<div class="xjzl-chat-card"><div class="card-content-wrapper"><p><b>祝咒引灵：</b></p><p>请手动移除自身和目标各一个状态。</p><p>请手动选中范围内友方，应用 <b>${huti}</b> 点护体。</p></div></div>`,
    speaker: ChatMessage.getSpeaker({actor: actor})
});

if (args.isHit) {
    const eff = thisItem.effects.getName("渡魂").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    eff.duration = { rounds: 99 };
    await game.xjzl.api.effects.addEffect(args.target, eff);
}

if (["poison"].includes(args.type) || args.element === "yin") {
    // 读取 flag 里存的动态数值
    const reduction = thisEffect.flags["xjzl-system"].damageReduction || 10;
    args.output.damage = Math.max(0, args.output.damage - reduction);
    actor.showFloatyText(`减免 ${reduction}`, { fill: "#00FF00" });
}

if (args.isHit) {
    // 计算 DC (基础17 + 升级2)
    const lvl = Math.max(1, move.computedLevel || 1);
    const dc = 17 + (lvl - 1) * 2;
    // 计算伤害
    const dmg = args.finalDamage;

    await Macros.requestSave({
        target: args.target,
        attacker: actor,
        type: "renxing",
        dc: dc,
        label: "离魂调 - 韧性抵抗",
        damageOnFail: { value: dmg, type: "hp" },
        onFail: "qixu", // 系统状态气虚
        failureText: "心神失守，真气溃散！"
    });
}

if (Macros.checkStance(actor, args)) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div class="card-content-wrapper"><p><b>阴路遥触发：</b></p><p>请手动操作 [尸傀] 移动到攻击者身旁。</p></div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

const lvl = Math.max(1, move.computedLevel || 1);
const dc = 15 + (lvl - 1) * 2;
const dist = 3 + (lvl - 1) * 3;

await Macros.requestSave({
    target: args.target,
    attacker: actor,
    type: "dingli",
    dc: dc,
    label: "迷魂引 - 定力抵抗",
    failureText: `眼神涣散，请解除架招，向施法者移动 ${dist} 米。`
});

const confirm = await foundry.applications.api.DialogV2.confirm({
    window: { title: "幽冥开 - 爆发选择" },
    content: `<p>是否消耗 <b>20</b> 内力并进行残疾检定以震慑敌魂？</p>`,
    yes: { label: "爆发", icon: "fas fa-bomb" },
    no: { label: "仅伤害", icon: "fas fa-times" }
});

if (confirm) {
    // 1. 扣除内力
    await actor.update({ "system.resources.mp.value": Math.max(0, actor.system.resources.mp.value - 20) });
    ui.notifications.info("已扣除 20 内力，共振爆发！");

    // 2. 发起残疾检定 (此处仅发送卡片提示玩家投掷，或者调用系统检定)
    await actor.rollAttributeTest("canji", { skipDialog: true, bonus: 0 }); // 假设系统有 canji，没有则提示手动
    // 实际系统可能用 rollDisabilityTable 或其他宏，这里发卡片提示更稳妥
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><p style="color:red"><b>请手动进行残疾检定！</b></p></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });

    // 3. 标记 flag 供 hit 使用
    args.flags.performBurst = true;
}

if (args.isHit && args.flags.performBurst) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const dc = 13 + (lvl - 1) * 3;

    await Macros.requestSave({
        target: args.target,
        attacker: actor,
        type: "renxing",
        dc: dc,
        label: "幽冥开 - 韧性抵抗",
        onFail: "unconscious",
        failureText: "魂魄震荡，陷入昏迷！"
    });
}
